import{_ as r,o as a,c as t,ai as l}from"./chunks/framework.iNbpOH0p.js";const p=JSON.parse('{"title":"安全、认证与权限","description":"","frontmatter":{},"headers":[],"relativePath":"doc/awesome-vue/安全、认证与权限.md","filePath":"doc/awesome-vue/安全、认证与权限.md"}'),i={name:"doc/awesome-vue/安全、认证与权限.md"};function n(h,e,o,s,u,c){return a(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="安全、认证与权限" tabindex="-1">安全、认证与权限 <a class="header-anchor" href="#安全、认证与权限" aria-label="Permalink to “安全、认证与权限”">​</a></h1><h2 id="数据验证" tabindex="-1">数据验证 <a class="header-anchor" href="#数据验证" aria-label="Permalink to “数据验证”">​</a></h2><ul><li><a href="https://github.com/ajv-validator/ajv" target="_blank" rel="noreferrer">Ajv</a> ⭐ 28k — 高性能JSON Schema验证器，支持JSON Schema draft-07及更高版本，支持自定义关键字和异步验证</li><li><a href="https://github.com/hapijs/joi" target="_blank" rel="noreferrer">Joi</a> ⭐ 20k — 强大的JavaScript对象schema验证库，支持链式API定义复杂验证规则</li><li><a href="https://github.com/typestack/class-validator" target="_blank" rel="noreferrer">Class Validator</a> ⭐ 10k — 基于装饰器的TypeScript/JavaScript类属性验证库，支持嵌套对象验证和自定义验证器，广泛用于NestJS等框架</li><li><a href="https://github.com/jackocnr/intl-tel-input" target="_blank" rel="noreferrer">intl-tel-input</a> ⭐ 7.8k — 国际电话号码输入与验证插件，支持200多个国家，自动格式化与验证</li><li><a href="https://github.com/ianstormtaylor/superstruct" target="_blank" rel="noreferrer">Superstruct</a> ⭐ 7k — 简洁直观的数据验证库，支持自定义类型和嵌套对象验证，适用于API参数校验</li><li><a href="https://github.com/icebob/fastest-validator" target="_blank" rel="noreferrer">Fastest Validator</a> ⭐ 7k — 高性能JavaScript验证库，每秒可执行数百万次验证，支持多种内置验证器和数据清理</li><li><a href="https://github.com/vorms/vorms" target="_blank" rel="noreferrer">Vorms</a> ⭐ 5k — 轻量级、高性能的前端表单验证库，支持React/Vue，零依赖仅3KB gzip</li><li><a href="https://github.com/ealush/vest" target="_blank" rel="noreferrer">Vest</a> ⭐ 2.6k — 声明式验证框架，语法风格类似Mocha/Jest，支持Vue/React/Svelte</li></ul><h2 id="加密与安全" tabindex="-1">加密与安全 <a class="header-anchor" href="#加密与安全" aria-label="Permalink to “加密与安全”">​</a></h2><ul><li><a href="https://github.com/auth0/node-jsonwebtoken" target="_blank" rel="noreferrer">jsonwebtoken</a> ⭐ 22.5k — JSON Web Token的JavaScript实现，支持JWT签名、验证和解析，Web认证的核心基础库</li><li><a href="https://github.com/brix/crypto-js" target="_blank" rel="noreferrer">crypto-js</a> ⭐ 16k — JavaScript加密标准库，支持AES、DES、Triple DES、Rabbit、SHA等多种加密算法</li><li><a href="https://github.com/zxcvbn-ts/zxcvbn" target="_blank" rel="noreferrer">@zxcvbn-ts/core</a> ⭐ 15k — 密码强度评估库（TypeScript重写版），基于真实密码数据集估算破解时间，支持多语言字典</li><li><a href="https://github.com/cure53/DOMPurify" target="_blank" rel="noreferrer">DOMPurify</a> ⭐ 12k — 高性能DOM-only XSS净化器，用于清理HTML、MathML和SVG内容，防止跨站脚本攻击</li><li><a href="https://github.com/openpgpjs/openpgpjs" target="_blank" rel="noreferrer">OpenPGP.js</a> ⭐ 5.9k — JavaScript版OpenPGP协议实现，支持加密、解密、签名和密钥管理，遵循RFC 9580标准</li><li><a href="https://github.com/dcodeIO/bcrypt.js" target="_blank" rel="noreferrer">bcrypt.js</a> ⭐ 5.8k — JavaScript BCrypt密码哈希算法实现，纯JavaScript编写无需原生编译，用于安全存储用户密码</li><li><a href="https://github.com/digitalbazaar/forge" target="_blank" rel="noreferrer">node-forge</a> ⭐ 5.3k — 原生JavaScript密码学工具集，包含AES/DES/RC4加密、RSA/ECC密钥、X.509证书、PKI、TLS等</li><li><a href="https://github.com/bitwiseshiftleft/sjcl" target="_blank" rel="noreferrer">SJCL</a> ⭐ 5k — 斯坦福大学开发的JavaScript加密库，支持AES加密、SHA-256哈希和HMAC，体积小且经过安全审计</li><li><a href="https://github.com/kjur/jsrsasign" target="_blank" rel="noreferrer">jsrsasign</a> ⭐ 2.4k — 纯JavaScript密码学库，支持RSA/ECDSA/DSA签名验证、X.509证书管理、JWT/JWS令牌处理</li><li><a href="https://github.com/panva/jose" target="_blank" rel="noreferrer">jose</a> ⭐ 2.2k — 全功能JWT、JWS、JWE、JWK实现库，支持多种加密和签名算法，适用于浏览器和Node.js</li><li><a href="https://github.com/paulmillr/noble-hashes" target="_blank" rel="noreferrer">noble-hashes</a> ⭐ 2k — 经过独立安全审计的哈希函数库，支持SHA2、SHA3、BLAKE3、RIPEMD等算法及HMAC、HKDF、Scrypt、Argon2等KDF</li><li><a href="https://github.com/indutny/elliptic" target="_blank" rel="noreferrer">elliptic</a> ⭐ 1.8k — 快速椭圆曲线加密纯JavaScript实现，支持secp256k1/ed25519/curve25519等曲线、ECDSA签名和ECDH密钥交换</li><li><a href="https://github.com/dchest/tweetnacl-js" target="_blank" rel="noreferrer">tweetnacl-js</a> ⭐ 1.6k — 高性能JavaScript加密库，提供NaCl加密实现，支持公钥加密、数字签名、哈希计算和安全随机数生成</li><li><a href="https://github.com/travist/jsencrypt" target="_blank" rel="noreferrer">jsencrypt</a> ⭐ 1.5k — JavaScript RSA加密解密库，基于OpenSSL生成的公钥/私钥对进行加解密操作</li><li><a href="https://github.com/emn178/js-md5" target="_blank" rel="noreferrer">js-md5</a> ⭐ 1.5k — 轻量级MD5哈希计算JavaScript库，支持字符串、ArrayBuffer和TypedArray类型输入</li><li><a href="https://github.com/pvorb/node-md5" target="_blank" rel="noreferrer">md5</a> ⭐ 1.5k — Node.js环境MD5哈希计算库，支持流式处理和大文件分块计算</li><li><a href="https://github.com/JuneAndGreen/sm-crypto" target="_blank" rel="noreferrer">sm-crypto</a> ⭐ 1.5k — 国密算法JavaScript实现，支持SM2非对称加密、SM3摘要算法、SM4对称加密等中国商用密码标准</li><li><a href="https://github.com/LeSuisse/vue-dompurify-html" target="_blank" rel="noreferrer">vue-dompurify-html</a> ⭐ 800 — Vue v-html指令的安全替代方案，基于DOMPurify自动清洗HTML内容，防止XSS攻击</li><li><a href="https://github.com/helmetjs/helmet" target="_blank" rel="noreferrer">Helmet.js</a> ⭐ 10.8k — Express 安全中间件，通过设置 HTTP 安全头保护 Vue SSR/Nuxt 应用免受 XSS、点击劫持等常见 Web 攻击</li></ul><h2 id="认证与授权" tabindex="-1">认证与授权 <a class="header-anchor" href="#认证与授权" aria-label="Permalink to “认证与授权”">​</a></h2><ul><li><a href="https://github.com/better-auth/better-auth" target="_blank" rel="noreferrer">Better Auth</a> ⭐ 28.1k — 全面的TypeScript认证与授权框架，支持Vue，内置2FA、多租户、OAuth插件生态</li><li><a href="https://github.com/stalniy/casl" target="_blank" rel="noreferrer">CASL</a> ⭐ 6.6k — 同构授权JavaScript库，支持前端和后端权限管理，可与Vue集成，实现细粒度资源访问控制</li><li><a href="https://github.com/casbin/node-casbin" target="_blank" rel="noreferrer">node-casbin</a> ⭐ 2.8k — 强大的访问控制库，支持ACL/RBAC/ABAC等多种授权模型，适用于Node.js和浏览器环境</li><li><a href="https://github.com/championswimmer/vuex-persist" target="_blank" rel="noreferrer">vuex-persist</a> ⭐ 2.5k — TypeScript就绪的Vuex插件，支持localStorage、sessionStorage和IndexedDB等多种存储方式</li><li><a href="https://github.com/prazdevs/pinia-plugin-persistedstate" target="_blank" rel="noreferrer">pinia-plugin-persistedstate</a> ⭐ 2.4k — 可配置的Pinia状态持久化插件，支持自定义存储、序列化器和状态过滤</li><li><a href="https://github.com/robinvdvleuten/vuex-persistedstate" target="_blank" rel="noreferrer">vuex-persistedstate</a> ⭐ 2.4k — 持久化Vuex状态，在页面刷新后保持应用状态</li><li><a href="https://github.com/tower1229/Vue-Access-Control" target="_blank" rel="noreferrer">Vue-Access-Control</a> ⭐ 2k — 基于Vue的前端访问控制方案，提供按钮级权限控制和动态路由权限管理</li><li><a href="https://github.com/websanova/vue-auth" target="_blank" rel="noreferrer">vue-auth</a> ⭐ 2k — Vue.js 3.x和2.x认证支持库，提供路由守卫、令牌刷新和社交登录集成</li><li><a href="https://github.com/dgrubelic/vue-authenticate" target="_blank" rel="noreferrer">vue-authenticate</a> ⭐ 1.5k — 轻量级身份验证库，支持本地登录/注册和GitHub、Facebook、Google等OAuth提供商</li><li><a href="https://github.com/DanSnow/vue-recaptcha" target="_blank" rel="noreferrer">vue-recaptcha</a> ⭐ 1.5k — Google reCAPTCHA的Vue组件，支持v2和v3版本，用于在Vue应用中集成人机验证，防止恶意提交</li><li><a href="https://github.com/dsb-norge/vue-keycloak-js" target="_blank" rel="noreferrer">vue-keycloak-js</a> ⭐ 1.3k — Vue.js集成Keycloak的认证插件，支持OpenID Connect、OAuth2和企业级SSO单点登录</li><li><a href="https://github.com/sidebase/nuxt-auth" target="_blank" rel="noreferrer">@sidebase/nuxt-auth</a> ⭐ 3.5k — Nuxt 3 专属认证模块，基于 Auth.js 构建，原生支持 OAuth2、Credentials、Magic Link 等 80+ 认证提供商，提供完整的 Session 管理和 SSR 支持</li><li><a href="https://github.com/apertureless/vue-password-strength-meter" target="_blank" rel="noreferrer">vue-password-strength-meter</a> ⭐ 1.1k — 基于zxcvbn的交互式密码强度检测Vue组件，支持密码显示/隐藏切换、自定义样式和实时反馈</li><li><a href="https://github.com/miladd3/vue-simple-password-meter" target="_blank" rel="noreferrer">vue-simple-password-meter</a> ⭐ 1.1k — 超轻量级密码强度检测组件，纯原生JS实现，压缩后不到1KB，支持Vue 2和Vue 3</li><li><a href="https://github.com/supertokens/supertokens-core" target="_blank" rel="noreferrer">SuperTokens</a> ⭐ 15.2k — 开源用户认证解决方案，支持邮箱密码、社交登录、无密码等多种认证方式，提供 Vue SDK 和自托管部署选项</li><li><a href="https://github.com/logto-io/logto" target="_blank" rel="noreferrer">Logto</a> ⭐ 10.5k — 现代化的身份认证基础设施，基于 OIDC 协议，提供 Vue/Nuxt SDK、多租户支持和完整的用户管理界面</li></ul><h2 id="权限管理与安全工具" tabindex="-1">权限管理与安全工具 <a class="header-anchor" href="#权限管理与安全工具" aria-label="Permalink to “权限管理与安全工具”">​</a></h2><ul><li><a href="https://github.com/vuejs/eslint-plugin-vue" target="_blank" rel="noreferrer">eslint-plugin-vue</a> ⭐ 4.6k — Vue官方ESLint插件，提供代码安全检查和最佳实践规则，可检测XSS漏洞、不安全的v-html使用和潜在注入风险</li><li><a href="https://github.com/produck/svg-captcha" target="_blank" rel="noreferrer">svg-captcha</a> ⭐ 4.5k — Node.js SVG验证码生成器，可与Vue前端配合使用，支持多种字符干扰和防识别策略</li><li><a href="https://github.com/theajack/disable-devtool" target="_blank" rel="noreferrer">disable-devtool</a> ⭐ 1.5k — 用于禁用浏览器开发者工具的JavaScript库，防止代码被调试和审查，支持多种检测模式</li><li><a href="https://github.com/victorybiz/vue-simple-acl" target="_blank" rel="noreferrer">Vue Simple ACL</a> ⭐ 900 — 简单灵活的Vue ACL插件，支持角色权限管理和RBAC模式，兼容Vue 2和Vue 3</li><li><a href="https://github.com/leonardovilarinho/vue-acl" target="_blank" rel="noreferrer">vue-acl</a> ⭐ 600 — 简单易用的Vue ACL插件，支持基于角色的权限管理和路由拦截</li><li><a href="https://github.com/casbin/casbin" target="_blank" rel="noreferrer">Casbin</a> ⭐ 19.2k — 强大的开源权限管理库，支持 ACL、RBAC、ABAC 等多种访问控制模型，提供多语言实现和 JavaScript/Vue 集成方案</li></ul><h2 id="安全审计与扫描" tabindex="-1">安全审计与扫描 <a class="header-anchor" href="#安全审计与扫描" aria-label="Permalink to “安全审计与扫描”">​</a></h2><ul><li><a href="https://github.com/zaproxy/zaproxy" target="_blank" rel="noreferrer">OWASP ZAP</a> ⭐ 13.5k — OWASP 开源 Web 安全扫描器，支持自动扫描和被动扫描，可集成到 CI/CD 中对 Vue 应用进行安全漏洞检测</li><li><a href="https://github.com/snyk/cli" target="_blank" rel="noreferrer">Snyk</a> ⭐ 5.2k — 开源安全平台 CLI 工具，自动检测 Vue 项目依赖中的已知安全漏洞和许可证问题，支持实时监控和修复建议</li><li><a href="https://github.com/DependencyTrack/dependency-track" target="_blank" rel="noreferrer">Dependency-Track</a> ⭐ 3.2k — OWASP 出品的持续组件分析平台，支持 SBOM 导入和漏洞告警，Vue 项目中用于第三方依赖的风险监控</li></ul><h2 id="隐私与合规工具" tabindex="-1">隐私与合规工具 <a class="header-anchor" href="#隐私与合规工具" aria-label="Permalink to “隐私与合规工具”">​</a></h2><ul><li><a href="https://github.com/orestbida/cookieconsent" target="_blank" rel="noreferrer">CMP (Consent Management)</a> ⭐ 4.1k — 轻量级 GDPR/CCPA Cookie 同意管理插件，纯 JavaScript 实现，零依赖，可轻松集成到 Vue.js 应用中管理用户隐私偏好</li><li><a href="https://github.com/jeremylong/DependencyCheck" target="_blank" rel="noreferrer">OWASP Dependency Check</a> ⭐ 6.8k — OWASP 依赖安全检查工具，通过 CVE 数据库比对 Vue 项目依赖，自动生成安全报告并标注重度漏洞</li></ul><h2 id="密钥与凭证管理" tabindex="-1">密钥与凭证管理 <a class="header-anchor" href="#密钥与凭证管理" aria-label="Permalink to “密钥与凭证管理”">​</a></h2><ul><li><a href="https://github.com/hashicorp/vault" target="_blank" rel="noreferrer">Vault</a> ⭐ 32.2k — HashiCorp 出品的密钥管理平台，支持动态密钥生成、加密存储和访问控制，Vue 后端服务中 API Key 和数据库密码的安全管理</li><li><a href="https://github.com/dotenv-org/dotenv-vault" target="_blank" rel="noreferrer">dotenv-vault</a> ⭐ 2.5k — .env 文件加密同步工具，将 Vue 项目的环境变量安全存储和团队共享，支持端到端加密和访问权限控制</li><li><a href="https://github.com/Infisical/infisical" target="_blank" rel="noreferrer">Infisical</a> ⭐ 18.7k — 开源密钥管理平台，提供 Web 管理界面和 CLI 工具，支持 Vue/Nuxt 等前端项目的环境变量集中管理和自动注入</li></ul><h2 id="生物识别与硬件认证" tabindex="-1">生物识别与硬件认证 <a class="header-anchor" href="#生物识别与硬件认证" aria-label="Permalink to “生物识别与硬件认证”">​</a></h2><ul><li><a href="https://github.com/fingerprintjs/fingerprintjs" target="_blank" rel="noreferrer">Fingerprint.js</a> ⭐ 24.4k — 浏览器指纹识别库，99.5% 准确率生成唯一访客 ID，Vue 项目中用于欺诈检测和异常登录识别</li></ul><h2 id="sso单点登录集成" tabindex="-1">SSO单点登录集成 <a class="header-anchor" href="#sso单点登录集成" aria-label="Permalink to “SSO单点登录集成”">​</a></h2><ul><li><a href="https://github.com/okta/okta-vue" target="_blank" rel="noreferrer">Okta Vue</a> ⭐ 1.5k — Okta 官方 Vue SDK，支持 OIDC/OAuth2 认证、MFA 多因素认证和 API 令牌管理，企业级 SSO 方案</li></ul><h2 id="安全编码规范检查" tabindex="-1">安全编码规范检查 <a class="header-anchor" href="#安全编码规范检查" aria-label="Permalink to “安全编码规范检查”">​</a></h2><ul><li><a href="https://github.com/eslint-community/eslint-plugin-security" target="_blank" rel="noreferrer">ESLint Plugin Security</a> ⭐ 2.5k — ESLint 安全插件，自动检测 Vue 代码中的 eval、不安全的正则和路径遍历等安全风险</li><li><a href="https://github.com/ecosia/vue-safe-html" target="_blank" rel="noreferrer">vue-safe-html</a> ⭐ 112 — Vue 指令，渲染经过净化的安全 HTML，基于 sanitize-html 过滤危险标签与脚本，防止 XSS 攻击，适合渲染用户提交的富文本内容。</li></ul>',21)])])}const k=r(i,[["render",n]]);export{p as __pageData,k as default};
